package com.bank.wshandshake.security;

import org.springframework.stereotype.Service;

@Service
public class TokenService {
    // Demo: a valid trader token. Real code verifies a signed JWT.
    public boolean isValid(String token) {
        return token != null && token.startsWith("token=trader-");
    }
    public String traderId(String token) {
        return token.substring("token=trader-".length());
    }
}
