package com.bank.wshandshake.ws;

import com.bank.wshandshake.security.TokenService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.*;
import org.springframework.http.server.*;
import org.springframework.web.socket.WebSocketHandler;
import org.springframework.web.socket.server.HandshakeInterceptor;
import java.util.Map;

// Runs DURING the handshake, BEFORE the 101 upgrade. Authentication must
// happen here, because after the upgrade there is no per-message HTTP auth.
public class AuthHandshakeInterceptor implements HandshakeInterceptor {

    private static final Logger log = LoggerFactory.getLogger(AuthHandshakeInterceptor.class);
    private final TokenService tokenService;

    public AuthHandshakeInterceptor(TokenService tokenService) {
        this.tokenService = tokenService;
    }

    @Override
    public boolean beforeHandshake(ServerHttpRequest request, ServerHttpResponse response,
                                   WebSocketHandler handler, Map<String, Object> attributes) {
        String query = request.getURI().getQuery();      // e.g. token=trader-rajesh
        if (!tokenService.isValid(query)) {
            response.setStatusCode(HttpStatus.UNAUTHORIZED);  // reject → no 101, stays HTTP
            log.warn("WebSocket handshake rejected: invalid token");
            return false;
        }
        // Stash the identity for the post-handshake session.
        attributes.put("traderId", tokenService.traderId(query));
        log.info("WebSocket handshake authorized for trader {}", attributes.get("traderId"));
        return true;   // true → server returns 101 Switching Protocols
    }

    @Override
    public void afterHandshake(ServerHttpRequest request, ServerHttpResponse response,
                               WebSocketHandler handler, Exception ex) {
        // Upgrade complete; connection is now WebSocket.
    }
}
