package com.bank.wshandshake.ws;

import com.bank.wshandshake.security.TokenService;
import org.springframework.context.annotation.Configuration;
import org.springframework.web.socket.config.annotation.*;

// Registers the handler AND the handshake interceptor, so auth runs before
// the upgrade for every connection to /ws/trading.
@Configuration
@EnableWebSocket
public class WebSocketConfig implements WebSocketConfigurer {

    private final TokenService tokenService;

    public WebSocketConfig(TokenService tokenService) {
        this.tokenService = tokenService;
    }

    @Override
    public void registerWebSocketHandlers(WebSocketHandlerRegistry registry) {
        registry.addHandler(new TradingHandler(), "/ws/trading")
                .addInterceptors(new AuthHandshakeInterceptor(tokenService))
                .setAllowedOrigins("https://app.bank.com");   // origin check
    }
}
